INSERT INTO STD_NYCPRF_PARTNER (RACE_WHITE,RACE_BLACK,RACE_ASIAN,RACE_OTHER,RACE_UNKNOWN,RACE_PACIFIC,RACE_INDIAN,RACE_CD,ETHNICITY,PATIENT_ID,NYCPRF_DOCUMENT_ID,PARTNRID,LNAME,FNAME,MNAME,BIRTH_SEX,CURRENT_GENDER,DVSCREEN,ALT_NAME,ADDRESS,CITY,STATE,ZIP,EMAIL,HOME_PHONE,CELL_PHONE,DOB_TEXT,AGE,WORK_PHONE,RISK_VIOLENCE,NOTIFIED_DATE,COMPLEXION_PARTNER,HAIR_PARTNER,HEIGHT,MARITAL_CODE,PREGNANT,PARTNER_ASSISTANCE_STATUS,ENTER_DATE,EHARS_DIAG_DATE_TEXT,CITYNO,PRIORITY,SOURCE,PARTNERS,REFERRAL,DISEASE_1,DISEASE_2,CODE,INTERVIEW,INTERVIEW_TYPE,REFERRAL_TYPE,PRINTED,NOTSEND,PARTNER_STATUS,ELICITED_BY_PNAP,PARTNER_TEST_DATE_TEXT,UPDATED_DATE,INFORMED_DATE,SPOUSE,HIGH_PRIORITY,INDEX_CITYNO,DISPO,HIVDISPO_DATE_TEXT,CREATE_UID,CREATE_DATE ) SELECT CASE WHEN UPPER(TRIM(PRTRACE)) = 'WHITE' THEN 1 ELSE 0 END RACE_WHITE , CASE WHEN UPPER(TRIM(PRTRACE)) = 'BLACK' THEN 1 ELSE 0 END RACE_BLACK , CASE WHEN UPPER(TRIM(PRTRACE)) = 'ASIAN' THEN 1 ELSE 0 END RACE_ASIAN , CASE WHEN UPPER(TRIM(PRTRACE)) IN ( '3','OTHER') THEN 1 ELSE 0 END RACE_OTHER , CASE WHEN UPPER(TRIM(PRTRACE)) = 'UNKNOWN' THEN 1 ELSE 0 END RACE_UNKNOWN , CASE WHEN UPPER(TRIM(PRTRACE)) LIKE '%HAWAIIAN%' THEN 1 ELSE 0 END RACE_PACIFIC , CASE WHEN UPPER(TRIM(PRTRACE)) = '5' THEN 1 ELSE 0 END RACE_INDIAN , CASE WHEN UPPER(TRIM(PRTRACE)) = 'WHITE' THEN '01' WHEN UPPER(TRIM(PRTRACE)) = 'BLACK' THEN '02' WHEN UPPER(TRIM(PRTRACE)) = 'ASIAN' THEN '04' WHEN UPPER(TRIM(PRTRACE)) IN ( '3','OTHER') THEN '06' WHEN UPPER(TRIM(PRTRACE)) = 'UNKNOWN' THEN '09' WHEN UPPER(TRIM(PRTRACE)) LIKE '%HAWAIIAN%' THEN '04' WHEN UPPER(TRIM(PRTRACE)) = '5' THEN '05' ELSE NULL END RACE_CD , CASE WHEN UPPER(TRIM(PRTRACE)) = '3' THEN '01' WHEN UPPER(TRIM(PRTCURGENDER)) = '01' THEN '01' WHEN UPPER(TRIM(PRTCURGENDER)) = '02' THEN '02' WHEN UPPER(TRIM(PRTCURGENDER)) = '09' THEN '09' WHEN UPPER(TRIM(PRTCURGENDER)) = 'Y' THEN '01' WHEN UPPER(TRIM(PRTCURGENDER)) = 'N' THEN '02' WHEN UPPER(TRIM(PRTCURGENDER)) = 'UN' THEN '09' WHEN UPPER(TRIM(PRTCURGENDER)) = 'UNK' THEN '09' WHEN UPPER(TRIM(PRTCURGENDER)) = 'U' THEN '09' END ETHNICITY , TRIM(PATIENTID),NYCPRF_DOCUMENT_ID,TRIM(PARTNERID),TRIM(UPPER(PRTLNAME)),TRIM(UPPER(PRTFNAME)),TRIM(UPPER(PRTMI)),TRIM(UPPER(PRTSEXBIRTH)),
CASE WHEN UPPER(TRIM(PRTCURGENDER)) = 'M' THEN 'M' WHEN UPPER(TRIM(PRTCURGENDER)) = 'F' THEN 'F' WHEN UPPER(TRIM(PRTCURGENDER)) = 'T' THEN 'T' WHEN UPPER(TRIM(PRTCURGENDER)) = 'U' THEN 'U' WHEN UPPER(TRIM(PRTCURGENDER)) = 'R' THEN 'R' WHEN UPPER(TRIM(PRTCURGENDER)) = 'X' THEN 'X' WHEN UPPER(TRIM(PRTCURGENDER)) = 'Y' THEN 'Y' WHEN UPPER(TRIM(PRTCURGENDER)) = 'H' THEN 'H' WHEN UPPER(TRIM(PRTCURGENDER)) = '1' THEN 'M' WHEN UPPER(TRIM(PRTCURGENDER)) = '2' THEN 'F' WHEN UPPER(TRIM(PRTCURGENDER)) = 'MTF' THEN 'F' WHEN UPPER(TRIM(PRTCURGENDER)) = 'FTM' THEN 'M' ELSE NULL END
,TRIM(UPPER(PRTDVIOLENCEDONE)),TRIM(UPPER(PRTALIAS)),TRIM(UPPER(PRTADDRESS)),TRIM(UPPER(PRTCITY)),TRIM(UPPER(PRTSTATE)),TRIM(UPPER(PRTZIP)),TRIM(UPPER( PRTEMAIL)),TRIM(UPPER(PRTHPHONE)),TRIM(UPPER(PRTCPHONE)),TRIM(UPPER(PRTDOB)),TRIM(PRTAGE),TRIM(UPPER(WRKTEL)),TRIM(UPPER(PRTRSKOFDVIOLENCE)),TRIM(UPPER(PRTDTNOFITIED)),TRIM(UPPER(PRTCOMPLEX)),TRIM(UPPER(PRTHAIR)),TRIM(UPPER(PRTHEIWEI)),TRIM(UPPER(PRTMARITALSTUS)),TRIM(UPPER(PRTPREGNANT)),TRIM(UPPER(PRTASSISSTATUS)),TRIM(UPPER(PRTENTERDT)),TRIM(UPPER(PRTDTHARSDX)),TRIM(UPPER(CITYNO)),TRIM(UPPER(PRIORITY)),SOURCE,P,TRIM(UPPER(REFERRAL)),TRIM(UPPER(DISEASE1)),TRIM(UPPER(DISEASE2)),TRIM(UPPER(CODE)),TRIM(UPPER(INTERV)),TRIM(UPPER(TYPEINTERV)),TRIM(UPPER(TYPEREF)),TRIM(UPPER(PRINTED)),TRIM(UPPER(NOTSEND)), CASE WHEN UPPER(TRIM(PRF_HIVSTUS)) = 'UNKNOWN' THEN 'U' WHEN UPPER(TRIM(PRF_HIVSTUS)) = 'NEGATIVE' THEN 'N' WHEN UPPER(TRIM(PRF_HIVSTUS)) = 'POSITIVE' THEN 'P' ELSE NULL END,TRIM(UPPER(PRF_ELICITED)),TRIM(UPPER(PRF_TSTDT)), fn_to_date(trim(UPDATED),'MM/DD/YYYY') UPDATED,fn_to_date(trim(PRIDTINF),'MM/DD/YYYY') PRIDTINF, TRIM(UPPER(PRF_SPOUSE)),TRIM(UPPER(HPRIORITY)),TRIM(UPPER(INDEXCITYNO)),TRIM(UPPER(PRTHVDISPO)),TRIM(UPPER(PRTHVDISPODT)),900,SYSDATE FROM RAW_NYCPRF_PARTNER where NYCPRF_DOCUMENT_ID = #{documentId}
